steps.solutionCode:
const root = ReactDOM.createRoot(document.querySelector('#root'));

const Card = ({ title, price }) => (
  <article className="card">
    <h3 className="card__title">{title}</h3>
    <p className="card__price">{price}</p>
  </article>
);

const second = <Card title="니트 베스트" price="245,000원" />;

root.render(
  <>
    <Card title="오버사이즈 셔츠" price="189,000원" />
    {second}
  </>
);

const root = ReactDOM.createRoot(document.querySelector('#root'));

const Card = ({ title, price = '가격 미정' }) => (
  <article className="card">
    <h3 className="card__title">{title}</h3>
    <p className="card__price">{price}</p>
  </article>
);

root.render(
  <>
    <Card title="오버사이즈 셔츠" price="189,000원" />
    <Card title="니트 베스트" price="245,000원" />
    <Card title="울 코트" price="590,000원" />
    <Card title="미공개 상품" />
  </>
);
